// Hue Saturation Value converter
vec4 hsv2rgb(float h, float s, float v, float a) {
    // Ensure h is in [0,1]
    h = fract(h);

    // Handle grayscale case
    if (s <= 0.0) {
        return vec4(v, v, v, a);
    }

    float hue = h * 6.0;
    int i = int(floor(hue));
    float f = hue - float(i);
    float p = v * (1.0 - s);
    float q = v * (1.0 - f * s);
    float t = v * (1.0 - (1.0 - f) * s);

    vec3 rgb;
    switch(i % 6) {
        case 0: rgb = vec3(v, t, p);  break;
        case 1: rgb = vec3(q, v, p);  break;
        case 2: rgb = vec3(p, v, t);  break;
        case 3: rgb = vec3(p, q, v);  break;
        case 4: rgb = vec3(t, p, v);  break;
        case 5: rgb = vec3(v, p, q);  break;
        default: rgb = vec3(v, p, q); break; // This should never happen
    }

    return vec4(rgb, a);
}
